/* From Uiverse.io by vikas7754  - Tags: input */
.__UIV_SCOPE__ .input {
  width: 100%;
  height: 100%;
  border: 2px solid rgba(255, 255, 255, 0.15);
  outline: none;
  z-index: 1;
  background: transparent;
  padding: 10px;
  padding-left: 35px;
  padding-right: 40px;
  font-size: 16px;
  border-radius: 16px;
  color: #fff;
}

.__UIV_SCOPE__ .input:focus {
  border: 1px solid rgb(242, 0, 255);
  background: #191919;
}

.__UIV_SCOPE__ .search-icon,
.__UIV_SCOPE__ .filter-icon {
  position: absolute;
  left: 10px;
  top: 55%;
  transform: translateY(-50%);
  z-index: 2;
}

.__UIV_SCOPE__ .filter-icon {
  left: unset;
  right: 10px;
}

.__UIV_SCOPE__ .circle-left,
.__UIV_SCOPE__ .circle-right {
  position: absolute;
  left: 25%;
  top: 40%;
  background: linear-gradient(rgb(255, 0, 242), rgb(255, 0, 195));
  width: 70px;
  height: 70px;
  border-radius: 50%;
  filter: blur(50px);
  z-index: -1;
}

.__UIV_SCOPE__ .circle-right {
  left: unset;
  right: 26%;
  top: 47%;
  background: linear-gradient(blue, rgb(255, 0, 230));
}

.__UIV_SCOPE__ .card {
  position: relative;
  height: 60px;
  width: 100%;
  max-width: 350px;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
  border-radius: 16px;
}

.__UIV_SCOPE__ .card::before {
  content: "";
  position: absolute;
  width: 50px;
  height: 600%;
  background: linear-gradient(#ff00e6, #ffffff33, #295bff);
  animation: animate 4s linear infinite;
}

.__UIV_SCOPE__ .card::after {
  content: "";
  inset: 1.5px;
  position: absolute;
  background: #0000002b;
  border-radius: 15px;
  backdrop-filter: blur(30px);
}

@keyframes animate {
  0% {
    transform: rotate(0deg);
  }
  50% {
    transform: rotate(180deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
